sys_script_include.script:
var TrainingCheckUtils = Class.create();
TrainingCheckUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    checkDuplicateSchedule: function() {
        var courseId = this.getParameter('sysparm_course');
        var trainingDate = this.getParameter('sysparm_date');
        var scheduleId = this.getParameter('sysparm_sys_id');

        var gr = new GlideRecord('x_1974477_skillnow_training_schedule');
        gr.addQuery('course', courseId);
        gr.addQuery('training_date', trainingDate); 

        if (scheduleId) {
            gr.addQuery('sys_id', '!=', scheduleId);
        }

        gr.query();

        if (gr.hasNext()) {
            return "true";
        }
        return "false";
    },

    type: 'TrainingCheckUtils'
});
